import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());long n = Long.parseLong(st.nextToken());long m = Long.parseLong(st.nextToken());long a = Long.parseLong(st.nextToken());long countN = (n + a - 1) / a;long countM = (m + a - 1) / a;System.out.println(countN * countM);}}